def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = 0
    for a in opp:
        if a == 'D':
            opp_def += 1
    me_def = 0
    for a in me:
        if a == 'D':
            me_def += 1

    last_me, last_opp = history[-1]

    if n >= 97:
        return 'D'

    recent = opp[-10:] if n >= 10 else opp
    rlen = len(recent)
    recent_def = 0
    for a in recent:
        if a == 'D':
            recent_def += 1
    recent_c = rlen - recent_def

    # Strongly defective opponent: protect and exploit long-run
    if opp_def * 10 >= n * 7:
        if recent_c >= 4 and last_opp == 'C':
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Opponent mostly cooperates: cooperate, but occasionally probe when safe
    if opp_def == 0:
        return 'C'

    if opp_def <= 2 and n >= 12:
        if rlen >= 6 and recent_def == 0:
            if rng.random() < 0.04:
                return 'D'
        return 'C'

    # Recent high defection: retaliate unless they clearly cooled down
    if rlen >= 4 and recent_def * 2 >= rlen:
        if recent_def == rlen:
            return 'D'
        if last_opp == 'C':
            if recent_def * 3 <= rlen:
                return 'C'
            if rng.random() < 0.3:
                return 'C'
        return 'D'

    # Tit-for-tat core with fast forgiveness to break DD loops
    if last_opp == 'D':
        # detect long streak of opponent defections
        streak = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if streak == 2:
            if rng.random() < 0.22:
                return 'C'
            return 'D'
        if me_def > 0 and opp_def * 4 < n and rng.random() < 0.3:
            return 'C'
        return 'D'

    # last_opp == 'C'
    # If we've been defecting and they kept cooperating, avoid over-exploiting
    if me_def >= 3 and opp_def == 0:
        return 'C'
    return 'C'
